// A year of weather for one place: every day's high, low and rain for the
// past twelve months from Open-Meteo's history, and the week ahead from its
// forecast. No key needed. Fetch it a few times a day at most: the past does
// not change.

function findPlace(query: string) {
  // "50.85, 4.35" skips the lookup.
  const pair = query.match(/^\s*(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)\s*$/)
  if (pair) {
    return { query, name: '', latitude: Number(pair[1]), longitude: Number(pair[2]) }
  }
  const known = frameos.recall('place')
  if (known && known.query === query) {
    return known
  }
  const answer = frameos.fetchJson(
    'https://geocoding-api.open-meteo.com/v1/search?count=1&format=json&name=' + encodeURIComponent(query),
  )
  const hit = answer && answer.results && answer.results[0]
  if (!hit) {
    throw new Error('Place not found: ' + query)
  }
  const place = { query, name: hit.name || query, latitude: hit.latitude, longitude: hit.longitude }
  frameos.remember('place', place)
  return place
}

function isoDate(epochMs: number) {
  return new Date(epochMs).toISOString().substring(0, 10)
}

export function get(app: FrameOSApp) {
  const query = String(app.config.location || '').trim()
  if (!query) {
    throw new Error('Set a location')
  }
  const place = findPlace(query)
  const fahrenheit = app.config.temperatureUnit === 'fahrenheit'
  const inches = app.config.precipitationUnit === 'inch'
  const common =
    'latitude=' + place.latitude + '&longitude=' + place.longitude + '&timezone=auto' +
    '&daily=temperature_2m_max,temperature_2m_min,precipitation_sum' +
    '&temperature_unit=' + (fahrenheit ? 'fahrenheit' : 'celsius') +
    '&precipitation_unit=' + (inches ? 'inch' : 'mm')

  // The forecast first: it says what day it is where the place is.
  const forecast = frameos.fetchJson('https://api.open-meteo.com/v1/forecast?' + common + '&past_days=3&forecast_days=8')
  if (!forecast || forecast.error || !forecast.daily) {
    throw new Error(forecast && forecast.reason ? forecast.reason : 'No forecast for ' + query)
  }
  const offset = forecast.utc_offset_seconds || 0
  const todayText = forecast.daily.time[3]
  const today = Date.parse(todayText + 'T00:00:00Z')
  const firstText = isoDate(today - 365 * 86400000)
  const lastText = isoDate(today - 4 * 86400000)
  const past = frameos.fetchJson(
    'https://archive-api.open-meteo.com/v1/archive?' + common + '&start_date=' + firstText + '&end_date=' + lastText,
  )
  if (!past || past.error || !past.daily) {
    throw new Error(past && past.reason ? past.reason : 'No history for ' + query)
  }

  // One row a day from the first day on: the history, then the forecast.
  const high: (number | null)[] = []
  const low: (number | null)[] = []
  const rain: (number | null)[] = []
  const round = (value: number | null) => (value == null ? null : Math.round(value * 10) / 10)
  const add = (daily: any) => {
    for (let i = 0; i < daily.time.length; i++) {
      high.push(round(daily.temperature_2m_max[i]))
      low.push(round(daily.temperature_2m_min[i]))
      rain.push(round(daily.precipitation_sum[i]))
    }
  }
  add(past.daily)
  // The forecast starts three days back, where the history stops.
  add(forecast.daily)

  return {
    place: place.name,
    offset,
    fahrenheit,
    units: { temperature: fahrenheit ? '°F' : '°C', precipitation: inches ? 'in' : 'mm' },
    // The first day, as the place's date at midnight UTC; `today` is its index.
    start: Date.parse(firstText + 'T00:00:00Z'),
    today: past.daily.time.length + 3,
    high,
    low,
    rain,
  }
}

