// A year of weather as one chart, in the manner of a newspaper's annual
// weather page: every day of the past twelve months as a bar from its low to
// its high, colored by how warm the day was, the week ahead in pale after
// today, the warmest and coldest days marked, and the rain month by month
// underneath.
import { celsius, temperatureColor, MONTHS, degrees } from './weather'

// The looks. "color" is the newspaper's; "high" is black on white for panels
// without color (1-bit and grey e-paper), where a grey level means nothing;
// "inks" is for color e-paper, which has six solid inks and no pale shades.
// Where a grey or pale shade carried meaning, the high and inks looks say it
// another way: the week ahead is drawn as the ends of its bars, and the
// unfinished month's rain as an outline.
type Theme = {
  name: 'color' | 'high' | 'inks'
  paper: string
  ink: string
  soft: string
  grid: string
  zero: string
  rain: string
  bar: (celsiusValue: number) => string
}

const THEMES: Record<string, Theme> = {
  color: { name: 'color', paper: '#f6f3ee', ink: '#26221d', soft: '#7d756b', grid: '#e2dcd2', zero: '#c9c0b3', rain: '#4f7fb3', bar: temperatureColor },
  high: { name: 'high', paper: '#ffffff', ink: '#000000', soft: '#000000', grid: '#000000', zero: '#000000', rain: '#000000', bar: () => '#000000' },
  inks: { name: 'inks', paper: '#ffffff', ink: '#000000', soft: '#000000', grid: '#ffff00', zero: '#000000', rain: '#0000ff', bar: inkFor },
}

// A day's temperature in one of the color e-paper's inks.
function inkFor(c: number) {
  if (c < 5) return '#0000ff'
  if (c < 14) return '#00a000'
  if (c < 21) return '#ffff00'
  return '#ff0000'
}

function themeOf(app: FrameOSApp): Theme {
  const mode = app.state.contrast || 'auto'
  if (mode === 'high' || (mode === 'auto' && app.frame.color === false)) return THEMES.high
  if (mode === 'color') return THEMES.color
  return app.frame.paper ? THEMES.inks : THEMES.color
}

export function get(app: FrameOSApp, context: FrameOSContext) {
  const W = context.imageWidth ?? app.frame.width
  const H = context.imageHeight ?? app.frame.height
  const year = app.config.weather || {}
  if (!year.high || !year.high.length) {
    throw new Error(year.error || 'No weather yet')
  }
  const theme = themeOf(app)
  const PAPER = theme.paper
  const INK = theme.ink
  const SOFT = theme.soft
  const RAIN = theme.rain
  const plain = theme.name === 'color'
  const f = year.fahrenheit
  const days = year.high.length
  const u = Math.min(W, H) / 100
  const pad = u * 5
  const portrait = H > W
  // Without pale shades every rule and bar sits on whole pixels: an edge half
  // on a pixel is a grey, which 1-bit and six-ink panels can only dither.
  const hair = (w: number) => (plain ? w : Math.max(1, Math.round(w)))
  const on = (v: number, w: number) => (plain ? v : hair(w) % 2 ? Math.floor(v) + 0.5 : Math.round(v))
  const px = (v: number) => (plain ? v : Math.round(v))
  const dotted = theme.name !== 'high' ? undefined : `${hair(u * 0.3)} ${Math.round(Math.max(3, u * 1.4))}`

  // Areas: the title, the temperature chart, the months, the rain. No word
  // under 13 pixels (a cap height of 9): a small panel's chart gives the room.
  const titleSize = Math.max(16, u * (portrait ? 6 : 6.4))
  const label = Math.max(13, u * (app.frame.paper ? 3.1 : 2.8))
  const left = pad + label * 2.4
  const right = W - pad
  const chartTop = pad + titleSize * 1.9
  const monthRain: { from: number; to: number; total: number; month: number }[] = []
  for (let i = 0; i < days; i++) {
    const date = new Date(year.start + i * 86400000)
    if (i === 0 || date.getUTCDate() === 1) {
      monthRain.push({ from: i, to: i, total: 0, month: date.getUTCMonth() })
    }
    const current = monthRain[monthRain.length - 1]
    current.to = i + 1
    current.total += year.rain[i] ?? 0
  }
  const monthWidth = (right - left) / 12.2
  const rainText = (total: number) => (year.units.precipitation === 'in' ? total.toFixed(1) : String(Math.round(total)))
  // Where a month is narrower than its rain's number, the numbers stand in two
  // rows over the tallest bar, every other month's in the upper one, so
  // neighbours never touch (on their bars, two rows could meet at one height).
  const rainWidth = (m: { total: number }) => rainText(m.total).length * label * 0.95 * 0.56
  const stagger = monthRain.some((m, k) => k > 0 && (rainWidth(m) + rainWidth(monthRain[k - 1])) / 2 + label * 0.3 > monthWidth)
  // The rain's numbers and bars keep a bar of a line and a half at least.
  const rainHeight = Math.max((H - chartTop) * 0.2, label * (stagger ? 4.5 : 3.5))
  const chartBottom = H - pad - rainHeight - label * 3.2
  const rainTop = chartBottom + label * 2.6
  const rainBottom = px(H - pad - label * 1.2)
  const step = (right - left) / days
  const x = (i: number) => left + i * step

  // The temperature axis, in steps of 5 (or 10 °F), every other one named
  // where the names would touch.
  const values = year.high.concat(year.low).filter((v: number | null) => v != null)
  const tick = f ? 10 : 5
  const lowest = Math.floor(Math.min(...values) / tick) * tick
  const highest = Math.ceil(Math.max(...values) / tick) * tick
  const y = (t: number) => chartBottom - ((t - lowest) / (highest - lowest)) * (chartBottom - chartTop)
  const every = (chartBottom - chartTop) / ((highest - lowest) / tick) < label * 1.3 ? 2 : 1

  const grid = []
  for (let t = lowest; t <= highest; t += tick) {
    const zero = t === 0 && !f
    grid.push(
      <line x1={px(left)} y1={on(y(t), u * (zero ? 0.3 : 0.18))} x2={px(right)} y2={on(y(t), u * (zero ? 0.3 : 0.18))} stroke={zero ? theme.zero : theme.grid} strokeWidth={hair(u * (zero ? 0.3 : 0.18))} strokeDasharray={zero ? undefined : dotted} />,
    )
    if (Math.round(t / tick) % every === 0) {
      grid.push(
        <text x={left - label * 0.5} y={y(t) + label * 0.35} fontFamily="FiraGO" fontSize={label} fill={SOFT} textAnchor="end">
          {degrees(t)}
        </text>,
      )
    }
  }

  // Months: a line where each starts, its name between, and its rain.
  const months = []
  const letters = monthWidth > label * 2.3 ? 3 : 1
  for (const m of monthRain) {
    const wide = m.to - m.from >= 12
    if (m.from > 0) months.push(<line x1={on(x(m.from), u * 0.18)} y1={px(chartTop)} x2={on(x(m.from), u * 0.18)} y2={px(rainBottom)} stroke={theme.grid} strokeWidth={hair(u * 0.18)} strokeDasharray={dotted} />)
    if (wide) {
      months.push(
        <text x={(x(m.from) + x(m.to)) / 2} y={chartBottom + label * 1.55} fontFamily="FiraGO" fontWeight={600} fontSize={label} fill={SOFT} textAnchor="middle">
          {MONTHS[m.month].substring(0, letters).toUpperCase()}
        </text>,
      )
    }
  }

  // The days. The week ahead is pale in color, and only the ends of its bars
  // where there are no pale shades.
  const bars = []
  const barWidth = Math.max(1, step * 0.82)
  const cap = px(Math.max(2, u * 0.5))
  let warmest = -1
  let coldest = -1
  for (let i = 0; i < days; i++) {
    const hi = year.high[i]
    const lo = year.low[i]
    if (hi == null || lo == null) continue
    const ahead = i > year.today
    const color = theme.bar(celsius((hi + lo) / 2, f))
    const top = px(y(hi))
    const height = Math.max(px(Math.max(1, u * 0.4)), px(y(lo)) - top)
    const bx = px(x(i) + step * 0.09)
    const bw = Math.max(1, px(x(i) + step * 0.09 + barWidth) - bx)
    if (ahead && plain) {
      bars.push(<rect x={bx} y={top} width={bw} height={height} fill={color} opacity={0.45} />)
    } else if (ahead) {
      bars.push(<rect x={bx} y={top} width={bw} height={Math.min(cap, height)} fill={color} />)
      if (height > cap) bars.push(<rect x={bx} y={top + height - cap} width={bw} height={cap} fill={color} />)
    } else {
      bars.push(<rect x={bx} y={top} width={bw} height={height} fill={color} />)
      if (warmest < 0 || hi > year.high[warmest]) warmest = i
      if (coldest < 0 || lo < year.low[coldest]) coldest = i
    }
  }

  const dateText = (i: number) => {
    const d = new Date(year.start + i * 86400000)
    return `${d.getUTCDate()} ${MONTHS[d.getUTCMonth()].substring(0, 3)}`
  }
  // A note beside a bar: on the side with room, on a card of paper so the
  // bars do not run through its words.
  const note = (i: number, atY: number, lines: string[], above: boolean) => {
    const toLeft = i > days * 0.7
    const nx = x(i) + (toLeft ? -label * 0.8 : label * 0.8) + step / 2
    const ny = atY + (above ? -label * 0.6 : label * 1.6)
    const top = above ? ny - (lines.length - 1) * label * 1.15 - label : ny - label
    const wide = Math.max(...lines.map((text) => text.length)) * label * 0.56 + label * 0.4
    return (
      <g>
        <line x1={x(i) + step / 2} y1={atY} x2={nx} y2={ny - (above ? -label * 0.2 : label * 0.9)} stroke={INK} strokeWidth={hair(u * 0.2)} />
        <rect x={toLeft ? nx - wide + label * 0.2 : nx - label * 0.2} y={top} width={wide} height={lines.length * label * 1.15 + label * 0.25} fill={PAPER} />
        {lines.map((text, k) => {
          const ty = ny + (above ? (k - lines.length + 1) * label * 1.15 : k * label * 1.15)
          return (
            <text x={nx} y={ty} fontFamily="FiraGO" fontWeight={k === 0 ? 600 : 400} fontSize={label} fill={k === 0 ? INK : SOFT} textAnchor={toLeft ? 'end' : 'start'}>
              {text}
            </text>
          )
        })}
      </g>
    )
  }

  // The rain, month by month: the month not over yet pale, or an outline.
  const rainMax = Math.max(1, ...monthRain.map((m) => m.total))
  const fullHeight = px(rainBottom - rainTop - label * (stagger ? 2.35 : 1.3))
  const rainBars = monthRain.map((m, k) => {
    const lift = stagger && k % 2 ? label * 1.05 : 0
    const height = px(((rainBottom - rainTop - label * (stagger ? 2.35 : 1.3)) * m.total) / rainMax)
    const x0 = px(x(m.from) + step * 2)
    const x1 = px(x(m.to) - step * 2)
    const total = rainText(m.total)
    const open = m.to - 1 > year.today
    const line = hair(Math.max(1, u * 0.35))
    return (
      <g>
        {open && !plain ? (
          <rect x={x0 + line / 2} y={rainBottom - height + line / 2} width={Math.max(1, x1 - x0 - line)} height={Math.max(0, height - line / 2)} fill={PAPER} stroke={RAIN} strokeWidth={line} />
        ) : (
          <rect x={x0} y={rainBottom - height} width={Math.max(1, x1 - x0)} height={height} fill={RAIN} opacity={open ? 0.5 : 1} />
        )}
        {m.to - m.from >= 12 ? (
          <text x={(x0 + x1) / 2} y={rainBottom - (stagger ? fullHeight : height) - label * 0.35 - lift} fontFamily="FiraGO" fontSize={label * 0.95} fill={SOFT} textAnchor="middle">
            {total}
          </text>
        ) : null}
      </g>
    )
  })
  let yearRain = 0
  for (let i = 0; i <= year.today && i < days; i++) yearRain += year.rain[i] ?? 0

  if (context.round === true) {
    return roundYear(W, H, year, days, monthRain, warmest, coldest, yearRain, theme)
  }

  const todayX = x(year.today) + step / 2
  // The title, shortened where it would run into "Today" at the chart's
  // corner (where the chart starts close enough under it to share its line).
  const todayTop = chartTop - label * 0.8 - label * 0.75
  const sharesLine = todayTop < pad + titleSize * 0.8 + titleSize * 0.2
  const todayRoom = sharesLine && todayX > right - label * 1.6 ? label * 3.4 + u * 2 : 0
  const place = year.place || 'town'
  const title =
    [`A year of weather in ${place}`, `A year in ${place}`, place].find((text) => pad + text.length * titleSize * 0.85 * 0.55 < right - todayRoom) || place
  const subtitle = plain ? 'Daily high and low · the week ahead in pale' : 'Daily high and low · ticks for the week ahead'
  const fitsSubtitle = pad + title.length * titleSize * 0.85 * 0.56 + subtitle.length * label * 0.52 + u * 4 < right
  const rainWords = `${year.units.precipitation === 'in' ? yearRain.toFixed(1) : Math.round(yearRain)} ${year.units.precipitation} of rain`
  const footer = [`${rainWords} in twelve months · Open-Meteo`, `${rainWords} in twelve months`, `${rainWords} in a year`].find(
    (text) => text.length * label * 0.5 < right - left,
  )
  return (
    <svg viewBox={`0 0 ${W} ${H}`} width={W} height={H}>
      <rect width={W} height={H} fill={PAPER} />
      <text x={pad} y={pad + titleSize * 0.8} fontFamily="FiraGO" fontWeight={600} fontSize={titleSize * 0.85} fill={INK}>
        {title}
      </text>
      <text x={right} y={pad + titleSize * 0.8} fontFamily="FiraGO" fontSize={label} fill={SOFT} textAnchor="end">
        {fitsSubtitle ? subtitle : ''}
      </text>
      {grid}
      {months}
      <line x1={on(todayX, u * 0.25)} y1={chartTop - label * 0.4} x2={on(todayX, u * 0.25)} y2={px(chartBottom)} stroke={INK} strokeWidth={hair(u * 0.25)} />
      <text x={todayX} y={chartTop - label * 0.8} fontFamily="FiraGO" fontWeight={600} fontSize={label} fill={INK} textAnchor={todayX > right - label * 1.6 ? 'end' : 'middle'}>
        Today
      </text>
      {bars}
      {warmest >= 0 ? note(warmest, y(year.high[warmest]), [`Warmest ${degrees(year.high[warmest])}`, dateText(warmest)], false) : null}
      {coldest >= 0 ? note(coldest, y(year.low[coldest]), [`Coldest ${degrees(year.low[coldest])}`, dateText(coldest)], true) : null}
      <text x={left - label * 0.5} y={rainTop + label * 0.4} fontFamily="FiraGO" fontWeight={600} fontSize={label} fill={RAIN} textAnchor="end">
        Rain
      </text>
      <text x={left - label * 0.5} y={rainTop + label * 1.6} fontFamily="FiraGO" fontSize={label * 0.9} fill={SOFT} textAnchor="end">
        {year.units.precipitation}
      </text>
      {rainBars}
      <line x1={px(left)} y1={on(rainBottom, u * 0.2)} x2={px(right)} y2={on(rainBottom, u * 0.2)} stroke={INK} strokeWidth={hair(u * 0.2)} />
      <text x={right} y={H - pad * 0.6} fontFamily="FiraGO" fontSize={label} fill={SOFT} textAnchor="end">
        {footer || ''}
      </text>
    </svg>
  )
}

// A round panel shows only the circle inside its square: the year goes round
// it, today at the top and the months clockwise from a year ago, each day a
// spoke from its low to its high, the rain month by month in a ring inside,
// and the place and its extremes in the middle (docs/scene-guide.md). The
// rings stay unnamed: any place for their degrees is on top of some days.
function roundYear(W: number, H: number, year: any, days: number, monthRain: { from: number; to: number; total: number; month: number }[], warmest: number, coldest: number, yearRain: number, theme: Theme) {
  const PAPER = theme.paper
  const INK = theme.ink
  const SOFT = theme.soft
  const RAIN = theme.rain
  const plain = theme.name === 'color'
  const f = year.fahrenheit
  const cx = W / 2
  const cy = H / 2
  const r = Math.min(W, H) / 2
  const u = r / 50
  const label = Math.max(14, Math.round(r * 0.062))
  const hair = (w: number) => (plain ? w : Math.max(1, Math.round(w)))
  const dotted = theme.name !== 'high' ? undefined : `${hair(u * 0.3)} ${Math.round(Math.max(3, u * 1.4))}`
  // A day's angle in turns: today at the top, the year before it clockwise.
  const turn = (i: number) => (i - year.today) / days
  const at = (radius: number, t: number) => [cx + Math.sin(t * Math.PI * 2) * radius, cy - Math.cos(t * Math.PI * 2) * radius]
  const f1 = (n: number) => n.toFixed(1)

  const values = year.high.concat(year.low).filter((v: number | null) => v != null)
  const tick = f ? 10 : 5
  const lowest = Math.floor(Math.min(...values) / tick) * tick
  const highest = Math.ceil(Math.max(...values) / tick) * tick
  const inner = r * 0.47
  const outer = r * 0.8
  const radiusOf = (t: number) => inner + ((t - lowest) / (highest - lowest)) * (outer - inner)

  const rings = []
  for (let t = lowest; t <= highest; t += tick) {
    const zero = t === 0 && !f
    rings.push(
      <circle cx={cx} cy={cy} r={radiusOf(t)} fill="none" stroke={zero ? theme.zero : theme.grid} strokeWidth={hair(u * (zero ? 0.35 : 0.2))} strokeDasharray={zero ? undefined : dotted} />,
    )
  }

  const spokes = []
  const width = Math.max(1, ((Math.PI * 2 * (inner + outer)) / 2 / days) * 0.8)
  const cap = Math.max(2, u * 0.6)
  for (let i = 0; i < days; i++) {
    const hi = year.high[i]
    const lo = year.low[i]
    if (hi == null || lo == null) continue
    const color = theme.bar(celsius((hi + lo) / 2, f))
    const ahead = i > year.today
    const from = radiusOf(lo)
    const to = Math.max(radiusOf(hi), radiusOf(lo) + u * 0.4)
    const spoke = (a: number, b: number) => {
      const [x1, y1] = at(a, turn(i + 0.5))
      const [x2, y2] = at(b, turn(i + 0.5))
      return <line x1={f1(x1)} y1={f1(y1)} x2={f1(x2)} y2={f1(y2)} stroke={color} strokeWidth={width} opacity={ahead && plain ? 0.45 : 1} />
    }
    if (ahead && !plain && to - from > cap * 2) {
      spokes.push(spoke(from, from + cap))
      spokes.push(spoke(to - cap, to))
    } else {
      spokes.push(spoke(from, to))
    }
  }

  // Months: a spoke where each starts, its name outside the ring.
  const rainInner = r * 0.36
  const rainOuter = r * 0.44
  const rainMax = Math.max(1, ...monthRain.map((m) => m.total))
  const months = []
  const rain = []
  for (const m of monthRain) {
    if (m.from > 0) {
      const [x1, y1] = at(rainInner, turn(m.from))
      const [x2, y2] = at(outer + u * 1.5, turn(m.from))
      months.push(<line x1={f1(x1)} y1={f1(y1)} x2={f1(x2)} y2={f1(y2)} stroke={theme.grid} strokeWidth={hair(u * 0.2)} strokeDasharray={dotted} />)
    }
    if (m.to - m.from >= 12) {
      const [lx, ly] = at(r * 0.885, turn((m.from + m.to) / 2))
      months.push(
        <text x={f1(lx)} y={f1(ly + label * 0.35)} fontFamily="FiraGO" fontWeight={600} fontSize={label} fill={SOFT} textAnchor="middle">
          {MONTHS[m.month].substring(0, 3).toUpperCase()}
        </text>,
      )
    }
    // The month's rain, a sector growing outward from the ring's inside.
    const from = turn(m.from) + 0.004
    const to = turn(m.to) - 0.004
    if (to > from && m.total > 0) {
      const reach = rainInner + ((rainOuter - rainInner) * m.total) / rainMax
      const [ax, ay] = at(reach, from)
      const [bx, by] = at(reach, to)
      const [cx2, cy2] = at(rainInner, to)
      const [dx, dy] = at(rainInner, from)
      const open = m.to - 1 > year.today
      rain.push(
        <path
          d={`M${f1(ax)} ${f1(ay)} A${f1(reach)} ${f1(reach)} 0 0 1 ${f1(bx)} ${f1(by)} L${f1(cx2)} ${f1(cy2)} A${f1(rainInner)} ${f1(rainInner)} 0 0 0 ${f1(dx)} ${f1(dy)} Z`}
          fill={open && !plain ? PAPER : RAIN}
          stroke={open && !plain ? RAIN : undefined}
          strokeWidth={open && !plain ? Math.max(1, u * 0.4) : undefined}
          opacity={open && plain ? 0.5 : 1}
        />,
      )
    }
  }

  const dot = (i: number, t: number) => {
    const [x, y] = at(radiusOf(t), turn(i + 0.5))
    return <circle cx={f1(x)} cy={f1(y)} r={u * 1.1} fill={PAPER} stroke={INK} strokeWidth={u * 0.4} />
  }
  const [tx1, ty1] = at(rainInner, 0)
  const [tx2, ty2] = at(outer + u * 0.8, 0)
  const total = `${year.units.precipitation === 'in' ? yearRain.toFixed(1) : Math.round(yearRain)} ${year.units.precipitation} of rain`
  return (
    <svg viewBox={`0 0 ${W} ${H}`} width={W} height={H}>
      <rect width={W} height={H} fill={PAPER} />
      {rings}
      {months}
      {rain}
      {spokes}
      <line x1={tx1} y1={ty1} x2={tx2} y2={ty2} stroke={INK} strokeWidth={u * 0.4} />
      {warmest >= 0 ? dot(warmest, year.high[warmest]) : null}
      {coldest >= 0 ? dot(coldest, year.low[coldest]) : null}
      <text x={cx} y={cy - label * 1.55} fontFamily="FiraGO" fontWeight={600} fontSize={label * 1.15} fill={INK} textAnchor="middle">
        {year.place || 'A year'}
      </text>
      <text x={cx} y={cy - label * 0.3} fontFamily="FiraGO" fontSize={label} fill={INK} textAnchor="middle">
        {warmest >= 0 ? `Warmest ${degrees(year.high[warmest])}` : ''}
      </text>
      <text x={cx} y={cy + label * 0.95} fontFamily="FiraGO" fontSize={label} fill={INK} textAnchor="middle">
        {coldest >= 0 ? `Coldest ${degrees(year.low[coldest])}` : ''}
      </text>
      <text x={cx} y={cy + label * 2.2} fontFamily="FiraGO" fontSize={label * 0.9} fill={RAIN} textAnchor="middle">
        {total}
      </text>
    </svg>
  )
}

